def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        # Remove hyphens and the last character (checksum)
        numbers = isbn.replace('-', '')[:-1]
        total = 0
        for i, num in enumerate(numbers):
            total += (i + 1) * int(num)
        checksum = total % 11
        return checksum

    def checksum_to_char(checksum: int) -> str:
        return 'X' if checksum == 10 else str(checksum)

    try:
        # Validate the format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("ISBN format is incorrect")

        # Calculate the expected checksum
        expected_checksum = calculate_checksum(isbn)

        # Get the provided checksum
        provided_checksum_char = isbn[-1]
        provided_checksum = 10 if provided_checksum_char == 'X' else int(provided_checksum_char)

        # Compare checksums
        if expected_checksum == provided_checksum:
            return "Right"
        else:
            # Construct the corrected ISBN
            corrected_checksum_char = checksum_to_char(expected_checksum)
            corrected_isbn = isbn[:-1] + corrected_checksum_char
            return corrected_isbn

    except (ValueError, IndexError) as e:
        return f"Invalid ISBN: {str(e)}"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid dimensions or number of aisles/chatting pairs")

    if K > M - 1 or L > N - 1:
        raise ValueError("Too many aisles for the given dimensions")

    horizontal_counts = [0] * M
    vertical_counts = [0] * N

    for (Xi, Yi), (Pi, Qi) in chatting_pairs:
        if Xi == Pi:
            # chatting in the same row
            if Yi < Qi:
                vertical_counts[Yi] += 1
            else:
                vertical_counts[Qi] += 1
        elif Yi == Qi:
            # chatting in the same column
            if Xi < Pi:
                horizontal_counts[Xi] += 1
            else:
                horizontal_counts[Pi] += 1
        else:
            # not in the same row or column, can't be separated by one aisle
            continue

    # Sort and get top K and L indices
    horizontal_indices = sorted(range(M), key=lambda x: horizontal_counts[x], reverse=True)[:K]
    vertical_indices = sorted(range(N), key=lambda x: vertical_counts[x], reverse=True)[:L]

    return (' '.join(map(str, sorted(horizontal_indices))), ' '.join(map(str, sorted(vertical_indices))))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")

    # dp[i][j] will store the number of ways to reach student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1  # Starting point

    for passes in range(1, m + 1):
        for student in range(n):
            # Pass the ball to the left neighbor
            dp[student][passes] += dp[(student - 1) % n][passes - 1]
            # Pass the ball to the right neighbor
            dp[student][passes] += dp[(student + 1) % n][passes - 1]

    return dp[0][m]

