def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or len(herbs) != M:
        raise ValueError("Invalid input parameters")

    # Create a DP array to store the maximum value that can be achieved with a given time limit
    dp = [0] * (T + 1)

    for time, value in herbs:
        if time > T:
            continue
        # Update the dp array from the back to avoid overwriting values that we still need to use
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    return dp[T]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # There is 1 way to arrange 0 pots: use no flowers
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if not c.isalpha():
            raise ValueError("Ciphertext must consist only of alphabetic characters.")
        if not k.isalpha():
            raise ValueError("Key must consist only of alphabetic characters.")
        shift = ord(k.lower()) - ord('a')
        if c.islower():
            return chr((ord(c) - shift - ord('a')) % 26 + ord('a'))
        else:
            return chr((ord(c) - shift - ord('A')) % 26 + ord('A'))

    if not key.isalpha():
        raise ValueError("Key must consist only of alphabetic characters.")
    if not ciphertext.isalpha():
        raise ValueError("Ciphertext must consist only of alphabetic characters.")

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext += chr(value + 65) if ciphertext[i].isupper() else chr(value + 97)

    return plaintext.lower()

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

