def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    left_increasing = [1] * n
    right_decreasing = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_decreasing[i] = right_decreasing[i + 1] + 1

    min_leaves = n
    for i in range(n):
        total_students = left_increasing[i] + right_decreasing[i] - 1
        min_leaves = min(min_leaves, n - total_students)

    return min_leaves

